 1→import { notFound } from 'next/navigation';
 2→import { ProjectContentWrapper } from '@/components/ProjectContentWrapper';
 3→import { ProjectDetailContent } from '@/components/ProjectDetailContent';
 4→import { ProjectHeroReel } from '@/components/ProjectHeroReel';
 5→import { ScrollReset } from '@/components/ScrollReset';
 6→import { projects, type Project } from '@/lib/projects';
 7→import { genAiProjects } from '@/lib/gen-ai-projects';
 8→import type { Metadata } from 'next';
 9→
10→interface ProjectPageProps {
11→  params: Promise<{ slug: string }>;
12→}
13→
14→// Combine all projects for lookup
15→const allProjects = [...projects, ...genAiProjects];
16→
17→function findProject(slug: string): Project | undefined {
18→  return allProjects.find(p => p.slug === slug);
19→}
20→
21→export async function generateStaticParams() {
22→  // Generate routes for both regular and Gen AI projects
23→  return allProjects.map((project) => ({
24→    slug: project.slug,
25→  }));
26→}
27→
28→export async function generateMetadata({ params }: ProjectPageProps): Promise<Metadata> {
29→  const { slug } = await params;
30→  const project = findProject(slug);
31→
32→  if (!project) {
33→    return {
34→      title: 'Project Not Found',
35→    };
36→  }
37→
38→  return {
39→    title: project.title,
40→    description: project.description,
41→    openGraph: {
42→      title: project.title,
43→      description: project.description,
44→      url: `https://josephibrahim.com/projects/${slug}`,
45→      type: 'article',
46→    },
47→    twitter: {
48→      card: 'summary_large_image',
49→      title: project.title,
50→      description: project.description,
51→    },
52→    alternates: {
53→      canonical: `https://josephibrahim.com/projects/${slug}`,
54→    },
55→  };
56→}
57→
58→export default async function ProjectPage({ params }: ProjectPageProps) {
59→  const { slug } = await params;
60→  const project = findProject(slug);
61→
62→  if (!project) {
63→    notFound();
64→  }
65→
66→  return (
67→    <>
68→      {/* Ensure scroll starts at top - user lands on autoplay hero */}
69→      <ScrollReset />
70→
71→      {/* Hero Reel - Fixed position autoplay, extends to top edge */}
72→      <ProjectHeroReel
73→        videoId={project.videoId}
74→        videoHash={project.videoHash}
75→        startTime={project.startTime}
76→        thumbnail={project.thumbnail}
77→      />
78→
79→      {/* Main content - positioned below hero with responsive marginTop */}
80→      <ProjectContentWrapper>
81→        <main
82→          className="mx-auto pb-32"
83→          style={{
84→            maxWidth: 'var(--max-content-width)',
85→            paddingTop: 'clamp(60px, 5vw + 30px, 100px)',
86→            paddingLeft: 'var(--side-padding)',
87→            paddingRight: 'var(--side-padding)'
88→          }}
89→        >
90→          <ProjectDetailContent project={project} />
91→        </main>
92→      </ProjectContentWrapper>
93→    </>
94→  );
95→}
